  1955	 *
  1956	 *  Creates a new object of <i>class</i>'s class, then
  1957	 *  invokes that object's <code>initialize</code> method,
  1958	 *  passing it <i>args</i>. This is the method that ends
  1959	 *  up getting called whenever an object is constructed using
  1960	 *  `.new`.
  1961	 *
  1962	 */
  1963	
  1964	mrb_value
  1965	mrb_instance_new(mrb_state *mrb, mrb_value cv)
  1966	{
  1967	  mrb_value obj, blk;
  1968	  const mrb_value *argv;
  1969	  mrb_int argc;
  1970	  mrb_sym init;
  1971	
  1972	  mrb_get_args(mrb, "*!&", &argv, &argc, &blk);
  1973	  obj = mrb_instance_alloc(mrb, cv);
  1974	  init = MRB_SYM(initialize);
  1975	  if (!mrb_func_basic_p(mrb, obj, init, mrb_do_nothing)) {
  1976	    mrb_funcall_with_block(mrb, obj, init, argc, argv, blk);
  1977	  }
  1978	  return obj;
  1979	}
  1980	
  1981	MRB_API mrb_value
  1982	mrb_obj_new(mrb_state *mrb, struct RClass *c, mrb_int argc, const mrb_value *argv)
  1983	{
  1984	  mrb_value obj;
  1985	  mrb_sym mid;
  1986	
  1987	  obj = mrb_instance_alloc(mrb, mrb_obj_value(c));
  1988	  mid = MRB_SYM(initialize);
  1989	  if (!mrb_func_basic_p(mrb, obj, mid, mrb_do_nothing)) {
  1990	    mrb_funcall_argv(mrb, obj, mid, argc, argv);
  1991	  }
  1992	  return obj;
  1993	}
