  1995	static mrb_value
  1996	mrb_class_initialize(mrb_state *mrb, mrb_value c)
  1997	{
  1998	  mrb_value a, b;
  1999	
  2000	  mrb_get_args(mrb, "|C&", &a, &b);
  2001	  if (!mrb_nil_p(b)) {
  2002	    mrb_yield_with_class(mrb, b, 1, &c, c, mrb_class_ptr(c));
  2003	  }
  2004	  return c;
  2005	}
