  2007	static mrb_value
  2008	mrb_class_new_class(mrb_state *mrb, mrb_value cv)
  2009	{
  2010	  mrb_int n;
  2011	  mrb_value super, blk;
  2012	  mrb_value new_class;
  2013	  mrb_sym mid;
  2014	
  2015	  n = mrb_get_args(mrb, "|C&", &super, &blk);
  2016	  if (n == 0) {
  2017	    super = mrb_obj_value(mrb->object_class);
  2018	  }
  2019	  new_class = mrb_obj_value(mrb_class_new(mrb, mrb_class_ptr(super)));
  2020	  mid = MRB_SYM(initialize);
  2021	  if (mrb_func_basic_p(mrb, new_class, mid, mrb_class_initialize)) {
  2022	    mrb_class_initialize(mrb, new_class);
  2023	  }
